import React, { forwardRef } from 'react';

import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import { _isStringChildren } from '../../core/utils/is-string-children.js';
import { Text } from '../../typography/Text.js';

//#region Typings
/** Accepted properties for the Avatar Label */
export interface AvatarLabelProps extends StylingProps, DataTestId {
  /** Elements to be displayed in the Avatar Label slot. */
  children: React.ReactNode;
}
//#endregion

/** Avatar Label component */
export const Label = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  AvatarLabelProps
>((props, forwardedRef) => {
  const {
    children,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
  }: AvatarLabelProps = props;
  const childIsText = _isStringChildren(children);

  return childIsText ? (
    <Text
      as="div"
      textStyle="base"
      ref={forwardedRef}
      className={consumerClassName}
      style={consumerStyle}
      data-testid={dataTestId}
    >
      {children}
    </Text>
  ) : (
    <div
      data-testid={dataTestId}
      ref={forwardedRef}
      className={consumerClassName}
      style={consumerStyle}
    >
      {children}
    </div>
  );
});

(Label as typeof Label & { displayName: string }).displayName = 'Avatar.Label';
